def _cart_position(event, item, membership=None, **kwargs):
    return CartPosition(
        event=event, item=item, price=23, expires=now() + timedelta(days=1), cart_id="123",
        used_membership=membership, **kwargs
    )


def _order_with_membership_usage(event, customer, item, membership, status=Order.STATUS_PAID):
    order = Order.objects.create(
        event=event, email='dummy@example.org', status=status, datetime=now(),
        expires=now() + timedelta(days=10), total=Decimal('23.00'), customer=customer,
    )
    OrderPosition.objects.create(order=order, item=item, price=Decimal('23.00'), used_membership=membership)
    return order


@pytest.mark.django_db
def test_validate_memberships_valid(event, customer, membership, requiring_ticket):
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, lock=True)


@pytest.mark.django_db
def test_validate_memberships_no_membership_for_required_product(event, customer, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket)], event)
    assert 'requires an active membership' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_guest_with_required_product(event, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(None, [_cart_position(event, requiring_ticket)], event)
    assert 'requires an active membership' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_membership_for_unrestricted_product(event, customer, membership, granting_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, granting_ticket, membership)], event)
    assert 'does not require a membership' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_other_customer(event, customer, membership, requiring_ticket):
    other = event.organizer.customers.create(email="jane@example.org")
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(other, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'different customer account' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_canceled(event, customer, membership, requiring_ticket):
    membership.canceled = True
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'canceled' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_test_mode_mismatch(event, customer, membership, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, testmode=True)
    assert 'test mode membership' in excinfo.value.message

    membership.testmode = True
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'test mode membership' in excinfo.value.message
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event, testmode=True)


@pytest.mark.django_db
def test_validate_memberships_type_not_allowed(event, customer, membership, requiring_ticket):
    other_type = event.organizer.membership_types.create(name="Other")
    membership.membership_type = other_type
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'not allowed for the product' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_event_outside_validity(event, customer, membership, requiring_ticket):
    membership.date_start -= timedelta(days=100)
    membership.date_end -= timedelta(days=100)
    membership.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'taking place at' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_ticket_validity_outside_membership(event, customer, membership, requiring_ticket):
    requiring_ticket.validity_mode = Item.VALIDITY_MODE_FIXED
    requiring_ticket.validity_fixed_from = datetime(2021, 5, 10, 0, 0, 0, 0, tzinfo=TZ)
    requiring_ticket.validity_fixed_until = datetime(2021, 5, 20, 0, 0, 0, 0, tzinfo=TZ)
    requiring_ticket.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'starts to be valid on' in excinfo.value.message

    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event,
                                  valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_memberships_max_usages(event, customer, membership, membership_type, requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    _order_with_membership_usage(event, customer, requiring_ticket, membership)
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'maximum amount' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_max_usages_ignores_order_being_changed(event, customer, membership, membership_type, requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    order = _order_with_membership_usage(event, customer, requiring_ticket, membership)
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event,
                                  ignored_order=order)


@pytest.mark.django_db
def test_validate_memberships_max_usages_within_batch(event, customer, membership, membership_type, requiring_ticket):
    membership_type.max_usages = 1
    membership_type.save()
    membership_type.allow_parallel_usage = True
    membership_type.save()
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [
            _cart_position(event, requiring_ticket, membership),
            _cart_position(event, requiring_ticket, membership),
        ], event)
    assert 'maximum amount' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_same_event_twice(event, customer, membership, requiring_ticket):
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [
            _cart_position(event, requiring_ticket, membership),
            _cart_position(event, requiring_ticket, membership),
        ], event)
    assert 'at the same time' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_same_event_twice_parallel_allowed(event, customer, membership, membership_type, requiring_ticket):
    membership_type.allow_parallel_usage = True
    membership_type.save()
    validate_memberships_in_order(customer, [
        _cart_position(event, requiring_ticket, membership),
        _cart_position(event, requiring_ticket, membership),
    ], event)


@pytest.mark.django_db
def test_validate_memberships_already_used_for_same_event(event, customer, membership, requiring_ticket):
    _order_with_membership_usage(event, customer, requiring_ticket, membership)
    with pytest.raises(ValidationError) as excinfo:
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
    assert 'at the same time' in excinfo.value.message


@pytest.mark.django_db
def test_validate_memberships_canceled_order_does_not_count(event, customer, membership, requiring_ticket):
    _order_with_membership_usage(event, customer, requiring_ticket, membership, status=Order.STATUS_CANCELED)
    validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)
